css:
.print-format {
    font-family: Arial, sans-serif;
    font-size: 12px;
    width: 80mm;
    margin: 0 auto;
}
.header {
    text-align: center;
    border-bottom: 2px solid #000;
    padding-bottom: 8px;
    margin-bottom: 10px;
}
.header h2 {
    margin: 0;
    font-size: 16px;
    text-transform: uppercase;
}
.section {
    margin-bottom: 12px;
}
.section-title {
    font-weight: bold;
    font-size: 13px;
    border-bottom: 1px dashed #000;
    padding-bottom: 3px;
    margin-bottom: 6px;
    text-transform: uppercase;
}
.info-row {
    display: flex;
    justify-content: space-between;
    margin: 4px 0;
}
.info-label {
    font-weight: bold;
}
table {
    width: 100%;
    border-collapse: collapse;
}
table th, table td {
    padding: 4px 2px;
    text-align: left;
    border-bottom: 1px dotted #ccc;
}
.amount {
    text-align: right;
}
.total-row {
    font-weight: bold;
    font-size: 14px;
    border-top: 2px solid #000;
    padding-top: 5px;
    margin-top: 10px;
}
.status-box {
    text-align: center;
    padding: 8px;
    margin: 10px 0;
    border: 2px solid #000;
    font-weight: bold;
}
.status-balanced {
    background-color: #d4edda;
    color: #155724;
}
.status-short {
    background-color: #f8d7da;
    color: #721c24;
}
.status-over {
    background-color: #fff3cd;
    color: #856404;
}
.signature-section {
    margin-top: 25px;
    padding-top: 10px;
    border-top: 1px dashed #000;
}
.signature-row {
    display: flex;
    justify-content: space-between;
    margin-top: 30px;
}
.signature-box {
    width: 45%;
    text-align: center;
}
.signature-line {
    border-top: 1px solid #000;
    margin-top: 25px;
    padding-top: 5px;
    font-size: 10px;
}
.footer {
    text-align: center;
    margin-top: 15px;
    font-size: 10px;
}
